// 도로시 재판 — 쟁점 1개 = 재판 1개, 전 5심(사용자 지정 2026-11-05). 제1심 「사랑받지 못한 채널」(① 에덴 기술 유출, 검사 노벨) · 제2심 「교관의 공소장」(② 라피 살해 미수, 검사 잉그리드) · 제3심 「방주에 닿은 방송」(③ 무허가 선동 방송, 검사 아이리) · 제4심 「도반의 법정」(④ 광장 사건, 검사 도반) · 제5심 「승리의 여신에게」(⑤ 갓데스 반역, 검사 버닝엄·재판장 엔더슨)
